contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 delay) public payable {
        require(delay >= 1);

        // First settle on a fresh c: no guess has ever been locked for msg.sender.
        uint256 balBefore = address(c).balance;
        bool revertedBeforeGuess;
        try c.settle() { revertedBeforeGuess = false; } catch { revertedBeforeGuess = true; }
        uint256 balAfterBeforeGuess = address(c).balance;

        // Lock in a guess; this is only attempted if the fresh settle behaved as required.
        require(revertedBeforeGuess);
        require(balAfterBeforeGuess == balBefore);

        c.lockInGuess{value: 1 ether}(bytes32(uint256(0x1234)));

        // The next block number is the block in which settle becomes possible.
        uint256 lockBlock = block.number + 1;
        require(block.number < lockBlock);

        bool revertedAfterGuess;
        try c.settle() { revertedAfterGuess = false; } catch { revertedAfterGuess = true; }

        assert(revertedAfterGuess && revertedBeforeGuess);
    }

    receive() external payable {}
}

